function hashNode(id):
    return crc32(id) & 0xffffffff

ring = []
for node in nodes:
    ring.append((hashNode(node.id), node))
ring.sort(key=lambda x: x[0])

function addVNode(node, count):
    for i in range(count):
        vnodeHash = hashNode(f"{node.id}-{i}")
        ring.append((vnodeHash, node))
ring.sort(key=lambda x: x[0])

function rehashOnJoin(newNode):
    pred = findPredecessor(newNode)
    for key in keysBetween(pred.hash, newNode.hash):
        moveKey(key, newNode)
function rehashOnLeave(removedNode):
    succ = findSuccessor(removedNode)
    for key in removedNode.keys:
        moveKey(key, succ)

function findNode(key):
    keyHash = hashKey(key)
    idx = bisectLeft(vnodeHashes, keyHash)
    if idx == len(vnodeHashes):
        idx = 0  # wrap around
    return vnodeNodes[idx]

function onNodeFailure(node):
    removeVnodes(node)
    for key in node.keys:
        replicateKey(key, findSuccessor(node))
function onNodeRecovery(node):
    addVnodes(node)
    syncMissingKeys(node)

function monitorVnodes():
    for vnode in ring:
        size = vnode.keyCount
        latency = vnode.avgLookup
        if size > THRESHOLD or latency > LATENCY_LIMIT:
            triggerRehash(vnode)
